#include <map>
#include <string>
using namespace std;

int main() {
    map<string, int> grades;
    grades["Popescu"] = 10;
    grades["Ionescu"] = 9;

    // Iterate with range-based for
    for (auto& [name, grade] : grades) {
        printf("%s: %d\n", name.c_str(), grade);
    }

    // Safe lookup
    auto it = grades.find("Ionescu");
    if (it != grades.end())
        printf("Found: %d\n", it->second);

    grades.erase("Popescu");
    return 0;
}

#include <set>
#include <multimap>
using namespace std;

// Custom comparator for set
struct DescendingOrder {
    bool operator()(int a, int b) const { return a > b; }
};

int main() {
    set<int, DescendingOrder> s = {5, 3, 8, 1};
    // Iterates: 8, 5, 3, 1

    multimap<string, int> mm;
    mm.insert({"Popescu", 9});
    mm.insert({"Popescu", 10}); // duplicate key allowed

    auto range = mm.equal_range("Popescu");
    for (auto it = range.first; it != range.second; ++it)
        printf("%d\n", it->second);
    return 0;
}

