#include <memory>
using namespace std;

int main() {
    // C++11 constructor
    unique_ptr<int> a(new int(10));

    // C++14 make_unique (preferred - exception safe)
    auto b = make_unique<int>(20);

    // Key methods
    int* raw = a.get();   // raw pointer (don't delete!)
    a.reset();            // delete and set to nullptr
    int* r = a.release(); // give up ownership, you must delete r

    // Move semantics
    auto c = move(b);     // b is now nullptr
    return 0;
}

#include <memory>
using namespace std;

int main() {
    auto sp1 = make_shared<int>(42);
    auto sp2 = sp1; // both own the int
    printf("Count: %ld\n", sp1.use_count()); // 2
    sp1.reset(); // sp1 released; count = 1
    printf("Count: %ld\n", sp2.use_count()); // 1
    // sp2 goes out of scope -> object deleted
    return 0;
}

#include <memory>
using namespace std;

struct B; // forward declaration
struct A {
    shared_ptr<B> b_ptr;
};
struct B {
    weak_ptr<A> a_ptr; // weak_ptr breaks the cycle!
};

int main() {
    auto a = make_shared<A>();
    auto b = make_shared<B>();
    a->b_ptr = b;
    b->a_ptr = a; // does NOT increment a's refcount
    // Both objects will be properly destroyed
    return 0;
}
